Q: Change paper size in microsoft report viewer A: <p><em>You can use installed paper size's in your system</em></p>
<pre><code>PageSettings a4 = new PageSettings();
foreach (PaperSize item in a4.PrinterSettings.PaperSizes)
{
    if (item.PaperName == &quot;A4&quot;)
    {
        a4.PaperSize = item;
        break;
    }
}
</code></pre>
<p>Here is this which provide you paper size name and their size's
<a href="https://i.sstatic.net/E3Qsj.png" rel="nofollow noreferrer">check this image for clear understanding</a></p>

Q: Add &quot;api&quot; prefix to every end point in Web API A: <p>You can custom <code>MvcOptionsExtensions</code> to set route prefix globally instead of change the route attribute manually.</p>
<p>Create custom <code>MvcOptionsExtensions</code>:</p>
<pre><code>public static class MvcOptionsExtensions
{
    public static void UseRoutePrefix(this MvcOptions opts, IRouteTemplateProvider routeAttribute)
    {
        opts.Conventions.Add(new RoutePrefixConvention(routeAttribute));
    }

    public static void UseRoutePrefix(this MvcOptions opts, string
    prefix)
    {
        opts.UseRoutePrefix(new RouteAttribute(prefix));
    }
}

public class RoutePrefixConvention : IApplicationModelConvention
{
    private readonly AttributeRouteModel _routePrefix;

    public RoutePrefixConvention(IRouteTemplateProvider route)
    {
        _routePrefix = new AttributeRouteModel(route);
    }

    public void Apply(ApplicationModel application)
    {
        foreach (var selector in application.Controllers.SelectMany(c =&gt; c.Selectors))
        {
            if (selector.AttributeRouteModel != null)
            {
                selector.AttributeRouteModel = AttributeRouteModel.CombineAttributeRouteModel(_routePrefix, selector.AttributeRouteModel);
            }
            else
            {
                selector.AttributeRouteModel = _routePrefix;
            }
        }
    }
}
</code></pre>
<p>Register in <code>Startup.cs</code> (versions before .NET 6) or in <code>Program.cs</code> (versions .NET 6 or later):</p>
<pre><code>services.AddControllers(o =&gt; {
    o.UseRoutePrefix(&quot;api&quot;);
});
</code></pre>
<p>Or:</p>
<pre><code>builder.Services.AddControllers(o =&gt; {
    o.UseRoutePrefix(&quot;api&quot;);
});
</code></pre>
